targets.expr:
1 - avg_over_time(
  (
    sum by (ip) (
      rate(node_cpu_seconds_total{job="static",mode="idle",ip=~"$host_ip"}[$__rate_interval])
    )
    / on (ip)
    count by (ip) (
      node_cpu_seconds_total{job="static",mode="idle",ip=~"$host_ip"}
    )
  )[$__range:]
)

sum by (ip, mode) (rate(node_cpu_seconds_total{job="static",ip=~"$host_ip"}[$__rate_interval]))/
on (ip) group_left count by (ip) (
  node_cpu_seconds_total{job="static",ip=~"$host_ip",mode="idle"}
)

sum by (ip) (rate(node_cpu_guest_seconds_total{job="static",ip=~"$host_ip"}[$__rate_interval]))/ on (ip) group_left count by (ip) (
  node_cpu_seconds_total{job="static",ip=~"$host_ip",mode="idle"}
)
